try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&saved.version===2&&saved.rows.length===25){state=upgrade(saved);loadMessage='저장된 작업을 불러왔습니다.';}else{const old=JSON.parse(localStorage.getItem(LEGACY)||'null');if(old){state=upgrade(migrate(old));loadMessage='이전 작업을 새 구성으로 불러왔습니다.';}}}catch{loadMessage='저장 내용을 불러오지 못했습니다. 기존 저장 데이터는 유지됩니다.';}
initializeLibrary();normalizeTeamSlots(state);metadata();render();document.getElementById('saveStatus').textContent=loadMessage;
function onEdit(e){const d=e.target.dataset,v=e.target.value;if(d.category!==undefined){state.categories[d.category]=v;persist();return;}if(d.waste!==undefined){state.waste[num(d.waste)][d.wasteField]=v;document.getElementById('wasteTotal').textContent='합계 '+kgFmt(wasteRows(state).reduce((n,w)=>n+Number(w.kg),0))+' kg';persist();return;}if(d.teamSlot!==undefined){const error=assignTeamSlot(state,num(d.team),num(d.teamSlot),v);if(error)alert(error);render();persist();return;}if(d.meta){state.meta[d.meta]=v;if(['startDate','endDate'].includes(d.meta)){state.meta.period=[state.meta.startDate,state.meta.endDate].filter(Boolean).join(' ~ ');const field=document.querySelector('[data-meta="period"]');if(field)field.value=state.meta.period;}}else if(d.row!==undefined){const i=num(d.row),c=num(d.col);if(c===29){const error=assignTeam(state,i,v);if(error){e.target.value=state.rows[i][c];alert(error);return;}}else {state.rows[i][c]=v;if(c===1&&!v.trim()){state.rows[i][29]='';state.rows[i][38]='';}if(c===28&&v){[4,6,8].forEach(day=>{if(isO(state.rows[i][day]))state.rows[i][day]=v;});document.querySelectorAll(`[data-row="${i}"]`).forEach(control=>{if([4,6,8].includes(num(control.dataset.col)))control.value=state.rows[i][num(control.dataset.col)];});}}}else if(d.label)state.labels[d.label]=v;else if(d.teamName!==undefined){state.teamNames[num(d.teamName)]=v;persist();return;}else if(d.note)state[d.note]=v;else return;refresh();persist();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-open-project]');if(b)openArchived(b.dataset.openProject);});
document.addEventListener('focusout',e=>{if(e.target.dataset.teamName!==undefined)render();});
document.addEventListener('input',onEdit);document.addEventListener('change',onEdit);
document.addEventListener('keydown',e=>{if(!['Enter','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)||e.isComposing||e.keyCode===229||e.altKey||e.ctrlKey||e.metaKey)return;const target=e.target;if(target.closest('.team-table')){e.preventDefault();const tr=target.closest('tr'),table=target.closest('table'),rows=[...table.tBodies[0].rows],cell=target.closest('td');let next;if(['ArrowLeft','ArrowRight'].includes(e.key)){const fields=[...tr.querySelectorAll('input:not([disabled]),select:not([disabled])')];next=fields[fields.indexOf(target)+(e.key==='ArrowLeft'?-1:1)];}else{const n=rows.indexOf(tr)+(e.key==='ArrowUp'||e.key==='Enter'&&e.shiftKey?-1:1);next=rows[n]?.cells[cell.cellIndex]?.querySelector('input:not([disabled]),select:not([disabled])');}if(next){next.focus();if(next.tagName==='INPUT')next.select();}return;}if(target.dataset.row===undefined)return;e.preventDefault();let next;const row=num(target.dataset.row),col=num(target.dataset.col);if(['ArrowLeft','ArrowRight'].includes(e.key)){const inputs=[...target.closest('tr').querySelectorAll('input:not([readonly]),select:not([disabled])')];next=inputs[inputs.indexOf(target)+(e.key==='ArrowLeft'?-1:1)];}else{const n=row+(e.key==='ArrowUp'||e.key==='Enter'&&e.shiftKey?-1:1);next=document.querySelector(`[data-row="${n}"][data-col="${col}"]`);}if(next&&!next.disabled&&!next.readOnly){next.focus();if(next.tagName==='INPUT'&&next.type!=='number')next.select();}});
